import java.util.Scanner;

public class Main {
    static long[][] choose = new long[501][501];

    static void compute_combinations(int maxN, int P) {
        for (int i = 0; i <= maxN; ++i) {
            choose[i][0] = 1;
            choose[i][i] = 1;
            for (int j = 1; j < i; ++j)
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % P;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int P = sc.nextInt();

        compute_combinations(N, P);

        long[] dp1 = new long[N + 1];
        long[] dpw = new long[N + 1];

        for (int i = 0; i <= N; i++) {
            dp1[i] = 0;
            dpw[i] = 1;
        }

        for (int m = 1; m <= M; ++m) {
            for (int i = 0; i < m; ++i) {
                long w = (dpw[i] * dpw[m - 1 - i]) % P;
                w = (w * choose[m - 1][i]) % P;
                dpw[m] = (dpw[m] + w * (m + 1)) % P;

                long s1 = (dp1[i] * dpw[m - 1 - i]) % P;
                long s2 = (dp1[m - 1 - i] * dpw[i]) % P;
                long add = ((s1 + s2) % P) * (m + 1) % P * choose[m - 1][i] % P;
                add = (add + w * (((long) i * (i + 1) + (long) (m - 1 - i) * (m - i)) / 2)) % P;
                dp1[m] = (dp1[m] + add) % P;
            }
        }

        long[][] dp = new long[N + 2][M + 2];
        long[][] dps = new long[N + 2][M + 2];

        for (int i = 0; i <= N + 1; i++) {
            for (int j = 0; j <= M + 1; j++) {
                dp[i][j] = 0;
                dps[i][j] = 0;
            }
        }

        dps[0][0] = 1;

        for (int i = 1; i <= N; ++i) {
            dp[i][i] = dp1[i];
            dps[i][i] = dpw[i];
            dps[i][0] = 1;
            for (int j = 1; j < i; ++j) {
                dp[i][j] = dp[i - 1][j];
                dps[i][j] = dps[i - 1][j];
                for (int k = 1; k <= j; ++k) {
                    dps[i][j] = (dps[i][j] + (dpw[k] * dps[i - k - 1][j - k] % P) * choose[j][k]) % P;
                    long add = ((dp[i - k - 1][j - k] * dpw[k]) % P + (dps[i - k - 1][j - k] * dp1[k]) % P) % P;
                    dp[i][j] = (dp[i][j] + add * choose[j][k]) % P;
                }
            }
        }

        System.out.println(dp[N][M]);
        sc.close();
    }
}

